package com.andye.warmod.antiair.client.audio;
import com.andye.warmod.WarMod;import com.andye.warmod.acoustics.ModSoundEvents;import com.andye.warmod.antiair.*;import com.andye.warmod.antiair.client.*;import java.util.*;import net.fabricmc.fabric.api.client.event.lifecycle.v1.*;import net.fabricmc.fabric.api.client.networking.v1.ClientPlayConnectionEvents;import net.minecraft.SharedConstants;import net.minecraft.client.Minecraft;import net.minecraft.client.multiplayer.ClientLevel;import net.minecraft.sounds.SoundEvent;import net.minecraft.util.Mth;import net.minecraft.world.phys.Vec3;
public final class AntiAirEngineAudioManager{private record Entry(AntiAirEngineLoopSound sound,AntiAirFlightPhase phase){}private static final Map<UUID,Entry> active=new LinkedHashMap<>();private static ClientLevel level;private static boolean registered;private AntiAirEngineAudioManager(){}public static void register(){if(registered)return;ClientTickEvents.END_CLIENT_TICK.register(AntiAirEngineAudioManager::tick);ClientPlayConnectionEvents.DISCONNECT.register((h,c)->clear(c));ClientLevelEvents.AFTER_CLIENT_LEVEL_CHANGE.register((c,l)->clear(c));registered=true;}private static synchronized void tick(Minecraft client){if(client.level==null||client.player==null){clear(client);return;}if(level!=null&&level!=client.level)clear(client);level=client.level;long time=client.level.getGameTime();Set<UUID> seen=new HashSet<>();for(AntiAirVisualState state:ClientAntiAirVisualManager.INSTANCE.snapshot()){seen.add(state.id());Entry entry=active.get(state.id());if(!state.thrust()){if(entry!=null&&entry.phase()!=state.phase())entry.sound().fadeOut(state.phase()==AntiAirFlightPhase.SELF_DESTRUCT?6:9);if(entry!=null)active.put(state.id(),new Entry(entry.sound(),state.phase()));continue;}Vec3 position=state.position(time,0);if(!position.isFinite())continue;double distance=client.player.getEyePosition().distanceTo(position);float gain=gain(distance)*(state.phase()==AntiAirFlightPhase.INTERCEPT?.78F:1F);if(entry==null&&gain>0){float pitch=state.variant()==AntiAirMissileVariant.MK_I?1.11F:1.18F;if(state.phase()==AntiAirFlightPhase.INTERCEPT)pitch+=.025F;AntiAirEngineLoopSound sound=new AntiAirEngineLoopSound(sound(distance),position,pitch);client.getSoundManager().play(sound);entry=new Entry(sound,state.phase());active.put(state.id(),entry);if(SharedConstants.IS_RUNNING_IN_IDE)WarMod.LOGGER.info("Anti-air engine started: id={}, variant={}",state.id(),state.variant());}if(entry!=null&&!entry.sound().isStopped())entry.sound().update(position,gain);}Iterator<Map.Entry<UUID,Entry>> it=active.entrySet().iterator();while(it.hasNext()){var e=it.next();if(!seen.contains(e.getKey())){client.getSoundManager().stop(e.getValue().sound());if(SharedConstants.IS_RUNNING_IN_IDE)WarMod.LOGGER.info("Anti-air engine stopped: id={}, phase={}",e.getKey(),e.getValue().phase());it.remove();}else if(e.getValue().sound().isStopped())it.remove();}}private static float gain(double d){if(d>1800)return 0;return Mth.clamp((float)(.72/(1+d/96)),.012F,.72F);}private static SoundEvent sound(double d){return d<140?ModSoundEvents.MISSILE_ENGINE_SUSTAIN_NEAR:d<400?ModSoundEvents.MISSILE_ENGINE_SUSTAIN_MEDIUM:d<850?ModSoundEvents.MISSILE_ENGINE_SUSTAIN_FAR:ModSoundEvents.MISSILE_ENGINE_SUSTAIN_EXTREME;}private static synchronized void clear(Minecraft client){for(Entry e:active.values())client.getSoundManager().stop(e.sound());active.clear();level=null;}}
